SET timezone = 'UTC';

-- ============================================================================
-- DROP ALL OBJECTS - Clean slate for database
-- ============================================================================
-- GENERATED FILE — DO NOT EDIT. Rewritten by every `effortless build`.
-- Generated by rulebook-to-postgres tool
-- ============================================================================

DO $$ 
DECLARE r RECORD; v_count INTEGER := 0;
BEGIN
    RAISE NOTICE 'Dropping views...';
    FOR r IN (SELECT table_name FROM information_schema.views WHERE table_schema = 'public') LOOP
        EXECUTE 'DROP VIEW IF EXISTS ' || quote_ident(r.table_name) || ' CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % views', v_count; v_count := 0;
    
    RAISE NOTICE 'Dropping functions...';
    FOR r IN (SELECT DISTINCT p.proname as function_name, pg_get_function_identity_arguments(p.oid) as function_args
              FROM pg_proc p JOIN pg_namespace n ON p.pronamespace = n.oid
              WHERE n.nspname = 'public' AND p.prokind = 'f') LOOP
        EXECUTE 'DROP FUNCTION IF EXISTS ' || quote_ident(r.function_name) || '(' || r.function_args || ') CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % functions', v_count; v_count := 0;
    
    RAISE NOTICE 'Dropping tables...';
    FOR r IN (SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE') LOOP
        EXECUTE 'DROP TABLE IF EXISTS ' || quote_ident(r.table_name) || ' CASCADE';
        v_count := v_count + 1;
    END LOOP;
    RAISE NOTICE 'Dropped % tables', v_count;
END $$;

-- ============================================================================
-- CREATE TABLES - Normalized data only (no calculated fields)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Events: Table: Events — top-level container (a festival, food bank shift, conference, etc.).
-- ----------------------------------------------------------------------------
CREATE TABLE events (
  event_id                            TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Display name of the event.
  event_date                          TIMESTAMPTZ         
);
COMMENT ON TABLE events IS 'Table: Events — top-level container (a festival, food bank shift, conference, etc.).';
COMMENT ON COLUMN events.name IS 'Display name of the event.';

-- ----------------------------------------------------------------------------
-- Volunteers: Table: Volunteers — people available to be slotted into shifts.
-- ----------------------------------------------------------------------------
CREATE TABLE volunteers (
  volunteer_id                        TEXT                 PRIMARY KEY,
  first_name                          TEXT                ,
  last_name                           TEXT                ,
  email_address                       TEXT                ,                     -- Used as the click-to-login identity.
  reliability_score                   NUMERIC             ,                     -- 0..1 — coordinator's confidence the volunteer will show up. Drives per-shift coverage weighting.
  max_hours                           NUMERIC                                   -- Volunteer's stated maximum hours for this scheduling period.
);
COMMENT ON TABLE volunteers IS 'Table: Volunteers — people available to be slotted into shifts.';
COMMENT ON COLUMN volunteers.email_address IS 'Used as the click-to-login identity.';
COMMENT ON COLUMN volunteers.reliability_score IS '0..1 — coordinator''s confidence the volunteer will show up. Drives per-shift coverage weighting.';
COMMENT ON COLUMN volunteers.max_hours IS 'Volunteer''s stated maximum hours for this scheduling period.';

-- ----------------------------------------------------------------------------
-- Shifts: Table: Shifts — a time block within an event needing N people with a required skill.
-- ----------------------------------------------------------------------------
CREATE TABLE shifts (
  shift_id                            TEXT                 PRIMARY KEY,
  name                                TEXT                ,                     -- Short label (e.g. "Setup Morning").
  event                               TEXT                ,                     -- Parent event.
  required_skill                      TEXT                ,                     -- Free-text skill tag (e.g. "setup", "intake", "food-handler").
  duration_hours                      NUMERIC             ,                     -- Length of the shift in hours; drives per-volunteer load.
  needed_count                        INTEGER                                   -- How many volunteers the coordinator wants on this shift.
);
COMMENT ON TABLE shifts IS 'Table: Shifts — a time block within an event needing N people with a required skill.';
COMMENT ON COLUMN shifts.name IS 'Short label (e.g. "Setup Morning").';
COMMENT ON COLUMN shifts.event IS 'Parent event.';
COMMENT ON COLUMN shifts.required_skill IS 'Free-text skill tag (e.g. "setup", "intake", "food-handler").';
COMMENT ON COLUMN shifts.duration_hours IS 'Length of the shift in hours; drives per-volunteer load.';
COMMENT ON COLUMN shifts.needed_count IS 'How many volunteers the coordinator wants on this shift.';

-- ----------------------------------------------------------------------------
-- Assignments: Table: Assignments — a volunteer slotted into a shift. Join table between Volunteers and Shifts (ERB does not allow direct many-to-many).
-- ----------------------------------------------------------------------------
CREATE TABLE assignments (
  assignment_id                       TEXT                 PRIMARY KEY,
  volunteer                           TEXT                ,
  shift                               TEXT                
);
COMMENT ON TABLE assignments IS 'Table: Assignments — a volunteer slotted into a shift. Join table between Volunteers and Shifts (ERB does not allow direct many-to-many).';

-- ============================================================================
-- FK INDEXES - Performance only, always applied
-- ============================================================================

-- Shifts
CREATE INDEX IF NOT EXISTS idx_shifts_event ON shifts (event);

-- Assignments
CREATE INDEX IF NOT EXISTS idx_assignments_volunteer ON assignments (volunteer);
CREATE INDEX IF NOT EXISTS idx_assignments_shift ON assignments (shift);

